INSERT INTO dep_map_nodes (id,name,short_name,x,y,transversal,objective,note,own_tasks,sort_order) VALUES ('ux','UX/UI','UX/UI',95,48,true,'Optimizar la disposición de los componentes en las pantallas de la demo para una experiencia más intuitiva. Cada equipo con tareas de frontend entrega un boceto o maqueta de sus vistas, que se evalúan para dar feedback y asegurar consistencia visual. Fecha de entrega: 30 sep.','Es transversal: aplica a todos los equipos con frontend, por eso no tiene dependencias en el mapa.','["Auditar y actualizar la librería de componentes y estilos","Eliminar scroll","Estandarizar paginado y lenguaje de la interfaz","Alinear tamaño de botones y modales","Estandarizar loadings y spinners (ya en proceso)"]'::jsonb,0);
