INSERT INTO dep_map_nodes (id,name,short_name,x,y,transversal,objective,note,own_tasks,sort_order) VALUES ('road','Roadmap','Roadmap',95,392,false,'Que el roadmap de cada curso-cohorte funcione con datos reales y el profesor lo pueda ajustar: las unidades salen de las secciones que gestiona en Cursos y edita cada nodo (reglas, obligatoriedad, vidas e ícono) sin que ningún alumno pierda progreso ni desbloqueos. El alumno lee el material de sus nodos de lectura y ve los ítems que compró en el Mercado, su posición en el ranking y sus insignias.',NULL,'["Sin datos simulados en el microservicio","Mundo 3D más liviano"]'::jsonb,6);
