-- Dependency map migrated from mapa-dependencias state.json (version 5).
CREATE TABLE dep_map_nodes (id text PRIMARY KEY, name text NOT NULL, short_name text NOT NULL, x integer NOT NULL, y integer NOT NULL, transversal boolean NOT NULL DEFAULT false, objective text, note text, own_tasks jsonb NOT NULL DEFAULT '[]'::jsonb, sort_order integer NOT NULL UNIQUE);
CREATE TABLE dep_map_kinds (id text PRIMARY KEY, label text NOT NULL, sort_order integer NOT NULL UNIQUE);
CREATE TABLE dep_map_edges (id text PRIMARY KEY, from_node text NOT NULL REFERENCES dep_map_nodes(id), to_node text NOT NULL REFERENCES dep_map_nodes(id), kind text NOT NULL REFERENCES dep_map_kinds(id), state text NOT NULL DEFAULT 'pendiente' CHECK (state IN ('pendiente','definir')), text text NOT NULL, done boolean NOT NULL DEFAULT false, done_by uuid REFERENCES users(id) ON DELETE SET NULL, sort_order bigserial NOT NULL, CONSTRAINT dep_map_edges_distinct_nodes CHECK (from_node <> to_node));
CREATE TABLE dep_map_activity (id bigserial PRIMARY KEY, ts timestamptz NOT NULL, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, actor_name text NOT NULL, summary text NOT NULL);
CREATE TABLE dep_map_meta (id integer PRIMARY KEY CHECK (id = 1), version bigint NOT NULL, updated_at timestamptz NOT NULL, updated_by text);
SELECT setval(pg_get_serial_sequence('dep_map_edges','sort_order'), COALESCE((SELECT MAX(sort_order) FROM dep_map_edges), 0), true);
SELECT setval(pg_get_serial_sequence('dep_map_activity','id'), COALESCE((SELECT MAX(id) FROM dep_map_activity), 1), true);
CREATE INDEX dep_map_edges_from_idx ON dep_map_edges(from_node);
CREATE INDEX dep_map_edges_to_idx ON dep_map_edges(to_node);
CREATE INDEX dep_map_activity_ts_idx ON dep_map_activity(ts DESC);
